13	/// Fixture MCP server with four tools:
14	/// - `echo`   — read-only annotated; echoes `{"msg": string}` back as text.
15	/// - `boom`   — always returns an `is_error` result.
16	/// - `shape`  — returns `structured_content` `{"ok": true}`.
17	/// - `sleepy` — sleeps for a minute before answering (cancellation tests).
18	#[derive(Clone, Default)]
19	pub struct FixtureServer;
