21	fn echo_schema() -> std::sync::Arc<rmcp::model::JsonObject> {
22	    let v = serde_json::json!({
23	        "type": "object",
24	        "properties": { "msg": { "type": "string" } },
25	        "required": ["msg"]
26	    });
27	    match v {
28	        serde_json::Value::Object(o) => std::sync::Arc::new(o),
